    internal static Style ItemStyle(){var style=new Style(typeof(ListBoxItem),Application.Current.Resources[typeof(ListBoxItem)] as Style);style.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(9,8,9,8)));style.Setters.Add(new Setter(FrameworkElement.MarginProperty,new Thickness(0,2,0,2)));style.Setters.Add(new Setter(Control.BorderBrushProperty,Brushes.Transparent));style.Setters.Add(new Setter(Control.BorderThicknessProperty,new Thickness(1)));style.Setters.Add(new Setter(Control.TemplateProperty,(ControlTemplate)System.Windows.Markup.XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='ListBoxItem'><Border Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}' CornerRadius='6' Padding='{TemplateBinding Padding}'><ContentPresenter TextElement.Foreground='{TemplateBinding Foreground}' VerticalAlignment='Center'/></Border></ControlTemplate>".Replace("'","\x27"))));var selected=new Trigger{Property=ListBoxItem.IsSelectedProperty,Value=true};selected.Setters.Add(new Setter(Control.BackgroundProperty,CompactTheme.WhiteSurface));selected.Setters.Add(new Setter(Control.BorderBrushProperty,CompactTheme.FieldLine));selected.Setters.Add(new Setter(Control.ForegroundProperty,FluentTheme.Accent));style.Triggers.Add(selected);return style;}
    internal static DataTemplate Template(){var row=new FrameworkElementFactory(typeof(DockPanel));var icon=new FrameworkElementFactory(typeof(TextBlock));icon.SetValue(TextBlock.FontFamilyProperty,new FontFamily("Segoe MDL2 Assets"));icon.SetValue(TextBlock.FontSizeProperty,15.0);icon.SetValue(FrameworkElement.WidthProperty,20.0);icon.SetValue(FrameworkElement.MarginProperty,new Thickness(0,0,8,0));icon.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);icon.SetBinding(TextBlock.TextProperty,new Binding{Converter=new GlyphConverter()});icon.SetValue(DockPanel.DockProperty,Dock.Left);row.AppendChild(icon);var text=new FrameworkElementFactory(typeof(TextBlock));text.SetValue(TextBlock.TextWrappingProperty,TextWrapping.Wrap);text.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);text.SetBinding(TextBlock.TextProperty,new Binding{Converter=new LanguageValueConverter()});row.AppendChild(text);return new DataTemplate{VisualTree=row};}
    sealed class GlyphConverter:IValueConverter{public object Convert(object value,Type type,object parameter,CultureInfo culture){string label=L.Display(value as string)??System.Convert.ToString(value);foreach(var item in Glyphs)if(String.Equals(label,L.Text(item.Key),StringComparison.CurrentCultureIgnoreCase))return item.Value;return "\uE8A5";}public object ConvertBack(object value,Type type,object parameter,CultureInfo culture){throw new NotSupportedException();}}
